-- =====================================================================
-- Cirdan · db/migraciones/003_textos_reglas.sql (RC-66, #30)
-- Catálogo de textos de las reglas del score: título, qué significa y qué
-- hacer, en español simple y sin siglas, para quien no es de sistemas.
-- 1. Crea scoring_rule_texts, con una fila por code. El code es estable
--    entre juegos de reglas, así un juego nuevo no copia los textos.
-- 2. Inserta los textos de las 30 reglas del juego v1: las 7 de la
--    semilla 001 y las 23 de la semilla 004 (#14 a #20 y #62 a #64).
-- 3. Agrega la FK scoring_rules.code -> scoring_rule_texts.code. Así la
--    base garantiza que toda regla tiene texto y que no se borra un texto
--    en uso.
-- Los textos van en una migración y no en una semilla por esa FK:
-- db/init/cargar_cirdan.sh corre todas las migraciones antes que las
-- semillas, y si los textos no existieran antes, la semilla 001 fallaría
-- al insertar sus reglas. En una base que ya existe, la FK se valida
-- contra las 7 reglas que ya tiene.
-- Catálogo global, como scoring_rules: sin RLS, y cirdan_app solo lee.
-- Corre en una sola transacción y se puede correr otra vez sin error.
-- En una base que ya existe se aplica a mano (ver db/README.md).
-- =====================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS scoring_rule_texts (
  code           text PRIMARY KEY CHECK (code ~ '^[a-z][a-z0-9_]{1,62}$'),
  title          text NOT NULL CHECK (btrim(title) <> ''),
  meaning        text NOT NULL CHECK (btrim(meaning) <> ''),
  recommendation text NOT NULL CHECK (btrim(recommendation) <> ''),
  reviewed_by    text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE scoring_rule_texts IS 'Textos de cada regla del score para el portal y la API: título, qué significa y qué hacer, en español simple y sin siglas. Una fila por code, que es estable entre juegos de reglas. Catálogo global sin RLS.';
COMMENT ON COLUMN scoring_rule_texts.code IS 'Mismo code de scoring_rules. Mismo formato que CODIGO_VALIDO de cirdan/recolectores/contrato.py.';
COMMENT ON COLUMN scoring_rule_texts.title IS 'Frase corta y simple, sin punto final.';
COMMENT ON COLUMN scoring_rule_texts.meaning IS 'Qué significa el hallazgo. Máximo dos frases.';
COMMENT ON COLUMN scoring_rule_texts.recommendation IS 'Qué hacer, en imperativo con tú. Máximo dos frases. La API lo devuelve con este mismo nombre.';
COMMENT ON COLUMN scoring_rule_texts.reviewed_by IS 'Quién revisó el texto (alguien de otra área y, en las reglas OSINT, Ernesto). NULL mientras no se revise.';

-- Los 30 textos van antes de la FK, en orden de id de la regla.
INSERT INTO scoring_rule_texts (code, title, meaning, recommendation) VALUES
 ('breach_exposure', 'Correos de la empresa en una filtración con contraseñas u otros datos de acceso que tenía menos de un año al detectarla', 'Al menos un correo de la empresa aparece en la filtración de datos de un servicio de internet que, cuando se detectó, había ocurrido hacía menos de un año e incluía contraseñas, preguntas de seguridad u otros datos para entrar a cuentas. Quien tenga esos datos puede intentar entrar a las cuentas de esas personas, también a las de la empresa si repiten la contraseña.', 'Pide a todo el personal que cambie ya la contraseña y las preguntas de seguridad de las cuentas que abrió con su correo de trabajo y de cualquier cuenta donde repita esa contraseña, sobre todo la de la empresa, y que cierre las sesiones abiertas. Activa la verificación en dos pasos en las cuentas de la empresa y, si quieres saber qué correos aparecen, consulta la búsqueda por dominio de Have I Been Pwned, que te pide verificar el dominio en ese servicio.'),
 ('cert_expired', 'Un sitio de la empresa tiene su certificado de seguridad vencido', 'Según los registros públicos de certificados, cuando se detectó, el más reciente de este sitio había vencido hacía menos de un año y, hasta donde se pudo comprobar, su nombre seguía apuntando a un servidor. Si el sitio sigue usando ese certificado, los navegadores muestran una alerta y la conexión deja de ser confiable para quien lo visita.', 'Renueva el certificado o, si el sitio ya no se usa, borra su nombre de la configuración del dominio. Activa la renovación automática para que no vuelva a pasar.'),
 ('outdated_software', 'Software que ya no recibe actualizaciones de seguridad del fabricante', 'Por la versión que muestra, un sitio o equipo de la empresa usa un programa o sistema operativo cuyo soporte ya terminó. Las fallas nuevas que se descubran en esa versión ya no se van a corregir.', 'Actualiza el software a una versión que todavía tenga soporte del fabricante. Si el reporte no dice qué programa es o no se puede actualizar pronto, revisa el equipo con su responsable y limita quién puede llegar a él desde internet.'),
 ('exposed_rdp', 'Puerto del escritorio remoto de Windows abierto a internet', 'Un equipo de la empresa tiene abierta a internet la entrada, o puerto, que suele usar el escritorio remoto de Windows, que permite manejarlo a distancia. Si de verdad es ese servicio, con una contraseña robada o adivinada alguien de fuera podría controlarlo.', 'Cierra ese puerto a internet y, si alguien necesita el escritorio remoto desde fuera, que entre solo por una conexión privada y cifrada a la red de la empresa con verificación en dos pasos. Pide esa conexión a tu proveedor de sistemas.'),
 ('dmarc_missing', 'El dominio no tiene una regla válida contra correos falsos a su nombre', 'El dominio no publica una regla válida que diga a los servidores de correo qué hacer con un mensaje falso enviado a su nombre, o publica dos y se ignoran. Así es más fácil engañar a clientes o empleados con correos que parecen de la empresa.', 'Publica en la configuración del dominio una sola regla contra correos falsos, con apoyo de tu proveedor de correo, en modo de solo observar y con los reportes activados a un buzón que revises. Cuando los reportes confirmen que tu correo legítimo pasa la revisión, cámbiala para que los correos falsos se rechacen, porque en modo de solo observar todavía no los frena.'),
 ('spf_missing', 'El dominio no publica una lista válida de servidores que pueden enviar su correo', 'El dominio no publica una lista válida de los servidores autorizados a enviar su correo, o la que publica no tiene efecto. Cualquiera puede mandar correos que parecen de la empresa con menos probabilidad de que los filtren.', 'Publica en la configuración del dominio una sola lista con los servidores que de verdad envían el correo de la empresa, con los datos exactos que te dé tu proveedor de correo. Si ya publicas una, revisa que su final rechace a los demás servidores.'),
 ('lookalike_domain', 'Dominio parecido al de la empresa con certificado de seguridad', 'Existe un dominio que no está dado de alta en este portal como de la empresa, se parece a su nombre y tiene o tuvo hace poco un certificado de seguridad. Puede ser de la propia empresa o de alguien legítimo, pero también puede usarse para crear sitios o correos falsos que suplanten a la empresa.', 'Si el dominio es de la empresa, dalo de alta en este portal. Si no, pide a tu área legal o a tu proveedor de seguridad que revise quién lo registró y qué publica, sin entrar tú al sitio, y si suplanta a la empresa, pide su baja a la empresa donde se registró y avisa a tus clientes.'),
 ('cert_expiring_soon', 'El certificado de seguridad de un sitio de la empresa vencía en menos de 30 días al detectarlo', 'Según los registros públicos de certificados, cuando se detectó, al más reciente de este sitio le quedaban menos de 30 días de vigencia. Si no se renueva a tiempo, los navegadores mostrarán una alerta a quien lo visite.', 'Renueva el certificado si todavía no lo hiciste y activa la renovación automática.'),
 ('domain_expiring_soon', 'El registro del dominio vencía en menos de 30 días al detectarlo', 'Cuando se detectó, la fecha de vencimiento del dominio caía dentro de los siguientes 30 días. Si nadie lo renueva, otra persona podría registrarlo y quedarse con el correo y las visitas de la empresa.', 'Renueva el dominio con la empresa donde lo registraste, si todavía no lo hiciste, y activa la renovación automática. Si ya está activa, confirma que el método de pago siga vigente.'),
 ('spf_allow_all', 'La lista de servidores del dominio deja enviar correo a cualquiera', 'La lista de servidores autorizados del dominio termina con una instrucción que acepta a todos. Un correo falso a nombre de la empresa pasa esa revisión como si fuera legítimo.', 'Cambia el final de la lista para que rechace o marque como sospechoso a cualquier servidor que no esté en ella. Pide a tu proveedor de correo el valor exacto.'),
 ('dmarc_policy_none', 'La regla del dominio contra correos falsos solo los observa y no los bloquea', 'El dominio tiene una regla contra correos falsos, pero está en modo de solo observar. Un correo falso a nombre de la empresa llega igual que si no hubiera regla.', 'Activa los reportes de la regla a un buzón que revises, si todavía no te llegan, y úsalos para confirmar que tu correo legítimo pasa la revisión. Después cambia la regla para que los correos falsos vayan a correo no deseado o se rechacen.'),
 ('secret_in_public_repo', 'Clave de acceso publicada en el código público de la empresa en GitHub', 'Un repositorio público de la empresa en GitHub, que es una carpeta de código que cualquiera puede ver, contiene una clave de acceso en su versión actual o en el historial de cambios que guarda. Cualquiera puede copiarla y, si sigue activa, entrar al servicio al que pertenece.', 'Cambia o anula la clave de inmediato en el servicio que la emitió, porque borrarla del código no basta. Después pide a quien programa que la quite del repositorio y de su historial de cambios y que guarde las claves fuera del código.'),
 ('email_in_public_commits', 'Correo de la empresa visible en los cambios publicados en GitHub', 'Este correo de la empresa aparece como autor de cambios en el código público de la organización en GitHub. Cualquiera puede verlo y usarlo para mandar correos engañosos a esa persona.', 'Pide a quienes publican en GitHub que usen en sus cambios el correo privado que GitHub les ofrece. Los cambios ya publicados se quedan, así que avisa a esa persona para que desconfíe de correos sospechosos.'),
 ('breach_exposure_old', 'Correos de la empresa en una filtración con contraseñas u otros datos de acceso que tenía más de un año al detectarla', 'Al menos un correo de la empresa aparece en la filtración de datos de un servicio de internet que, cuando se detectó, había ocurrido hacía más de un año e incluía contraseñas, preguntas de seguridad u otros datos para entrar a cuentas. El riesgo sigue si esas personas no cambiaron esos datos o repiten la contraseña en otros servicios.', 'Pide a todo el personal que cambie la contraseña y las preguntas de seguridad de cualquier cuenta donde todavía use las de entonces, sobre todo la de la empresa. Activa la verificación en dos pasos en las cuentas de la empresa y, si quieres saber qué correos aparecen, consulta la búsqueda por dominio de Have I Been Pwned, que te pide verificar el dominio en ese servicio.'),
 ('breach_exposure_no_passwords', 'Correos de la empresa en una filtración de datos sin contraseñas ni otros datos de acceso', 'Al menos un correo de la empresa aparece en la filtración de datos de un servicio de internet que no incluye contraseñas ni otros datos para entrar a cuentas, sino datos como el propio correo, nombres o teléfonos. Esos datos sirven para mandar correos falsos dirigidos a esas personas.', 'Pide a todo el personal que desconfíe de correos o llamadas que pidan datos o pagos, porque el reporte no dice qué correos aparecen. Refuerza en la empresa cómo reconocer un correo falso.'),
 ('personal_email_exposed', 'Correo de un servicio gratuito ligado a la empresa visible en internet', 'Un correo de un servicio gratuito, como los de uso personal, aparece ligado a la empresa en su sitio, en GitHub o en un perfil público. Esa cuenta queda fuera de los controles de la empresa y facilita que alguien se haga pasar por la empresa o por quien la usa.', 'Si es el contacto oficial, cámbialo por un buzón con el dominio de la empresa, y si es de alguien del equipo, pídele que lo quite de esas páginas y perfiles y que use su correo de trabajo. Si es de alguien ajeno, como un cliente en un testimonio, quítalo de tus páginas.'),
 ('email_pattern_exposed', 'Se puede deducir el formato de los correos de la empresa', 'Varios correos públicos de la empresa siguen el mismo formato basado en el nombre de cada persona. Con solo un nombre, cualquiera puede adivinar el correo de un empleado y mandarle correos falsos.', 'Reduce los correos con nombre de persona que aparecen en el sitio y en GitHub y usa buzones generales, como contacto o ventas, para lo público. Capacita al personal para reconocer correos falsos dirigidos.'),
 ('exposed_remote_admin', 'Control a distancia por comandos o pantalla compartida abierto a internet', 'Un equipo de la empresa tiene abierto a internet un servicio, distinto del escritorio remoto de Windows, para manejarlo a distancia por comandos o viendo su pantalla. Con una contraseña robada o adivinada, alguien de fuera podría controlarlo.', 'Cierra ese servicio a internet y permite administrar el equipo solo por una conexión privada y cifrada a la red de la empresa con verificación en dos pasos, que puede darte tu proveedor de sistemas. Si es un servicio antiguo que manda la contraseña sin cifrar, apágalo y usa uno cifrado.'),
 ('exposed_file_sharing', 'Puerto para compartir archivos abierto a internet', 'Un equipo de la empresa tiene abierta a internet una entrada, o puerto, de las que suelen usar los servicios para compartir archivos. Si de verdad es uno de esos servicios, con una contraseña o una falla conocida alguien de fuera podría leer o cambiar esos archivos.', 'Cierra ese puerto a internet y comparte archivos solo dentro de la red de la empresa o con una herramienta que pida verificación en dos pasos.'),
 ('exposed_database', 'Base de datos abierta a internet', 'Un equipo de la empresa deja abierta a internet la entrada a una base de datos. Con una contraseña o un error de configuración, alguien de fuera podría leer o cambiar sus datos.', 'Cierra la base de datos a internet y deja que solo la usen los sistemas de la empresa que la necesitan. Confirma con quien la administra que pida contraseña y cambia las que tenga de fábrica.'),
 ('exposed_ot_device', 'Equipo de control industrial abierto a internet', 'Un equipo que controla procesos industriales o de edificios responde desde internet con un lenguaje de comunicación industrial. Esa comunicación casi nunca pide contraseña, así que cualquiera que llegue podría leer o cambiar valores del proceso.', 'Quita cuanto antes el acceso desde internet a ese equipo, coordinado con quien opera el proceso para no detenerlo, y deja el acceso remoto solo por una conexión privada y cifrada a la red de la empresa con verificación en dos pasos. Revisa con el proveedor del equipo cómo separarlo de la red de oficina.'),
 ('exposed_iot_device', 'Dispositivo conectado, como una cámara o un módem, abierto a internet', 'Un dispositivo como una cámara, un grabador de video, un módem o una impresora responde desde internet. Con la contraseña de fábrica o una falla conocida, alguien de fuera podría tomar el control o ver lo que transmite.', 'Cierra el acceso desde internet al dispositivo, o solo a su página de administración si es el módem de la empresa, y si hace falta usarlo desde fuera hazlo por una conexión privada y cifrada a la red de la empresa que te dé tu proveedor de sistemas. Cambia su contraseña de fábrica y actualiza su programa interno.'),
 ('exposed_service', 'Servicio de la empresa abierto a internet que conviene revisar', 'Un equipo de la empresa tiene abierta a internet una entrada distinta de las usuales para sitios web y correo. Por sí sola no da acceso, pero cada entrada abierta es una puerta más que alguien puede intentar usar.', 'Confirma si ese servicio debe estar abierto a internet. Si no se usa o es solo interno, ciérralo o limita quién puede conectarse.'),
 ('known_vulnerability', 'Posible falla de seguridad conocida según la versión del software', 'Según la versión de software que muestra un equipo o sitio de la empresa, podría tener una falla de seguridad ya publicada. Es solo una posibilidad, porque se deduce por la versión y la falla puede estar corregida aunque la versión no cambie.', 'Confirma con el responsable del sistema si esa falla aplica a tu versión y, si aplica, instala la actualización del fabricante. Atiende primero las fallas marcadas como más graves.'),
 ('server_version_disclosed', 'El sitio revela qué programa y versión usa', 'En la información técnica que manda con cada respuesta, el sitio dice qué programa usa y en qué versión. Eso ayuda a un atacante a buscar fallas conocidas de esa versión sin tener que adivinar.', 'Configura el servidor del sitio para que no muestre el nombre ni la versión de sus programas. Mantén la versión al día aunque ya no se vea.'),
 ('public_bucket', 'Almacenamiento en la nube con su lista de archivos abierta a cualquiera', 'Un espacio de almacenamiento en la nube ligado a la empresa permite que cualquiera vea la lista de sus archivos sin iniciar sesión. No se revisó el contenido de los archivos, así que no se sabe si hay datos sensibles.', 'Quita el acceso público al almacenamiento si no es a propósito y revisa qué archivos contiene. Si debe ser público, confirma que no guarde datos internos ni de clientes.'),
 ('subdomain_takeover_risk', 'Dirección web de la empresa que otra persona podría tomar', 'Un subdominio de la empresa, que es una dirección que termina en su dominio, apunta a un espacio de almacenamiento en la nube que ya no existe. Otra persona podría crear un espacio con ese mismo nombre y publicar lo que quiera en esa dirección de la empresa.', 'Borra el subdominio de la configuración del dominio si ya no se usa, o vuelve a crear el espacio de almacenamiento a nombre de la empresa. Revisa también los demás subdominios que apunten a servicios que ya no usas.'),
 ('exposed_api_docs', 'Documentación técnica de un servicio web a la vista de todos', 'Un subdominio de la empresa, que es una dirección que termina en su dominio, publica la documentación técnica de un servicio web, con sus funciones y datos de entrada. Por sí sola no da acceso, pero le da a un atacante un mapa para preparar un ataque.', 'Quita la documentación de internet o pide inicio de sesión para verla. Déjala pública solo si el servicio está pensado para usarse desde fuera.'),
 ('api_auth_not_declared', 'Funciones de un servicio web que su documentación no marca como protegidas', 'La documentación publicada del servicio web tiene funciones que no declaran pedir inicio de sesión ni otra forma de identificación. Es solo lo que dice el documento, porque esas funciones no se probaron, y puede que sí la pidan.', 'Revisa con el equipo de desarrollo si esas funciones piden identificación y corrige la documentación o el servicio. Atiende primero las funciones que crean, cambian o borran datos.'),
 ('secret_in_container_image', 'Clave de acceso en una imagen de contenedor, un paquete público para correr un programa en servidores', 'Una imagen de contenedor pública de la empresa, que es un paquete con un programa listo para correr en servidores, guarda una clave de acceso en su configuración o en los pasos con que se armó. Cualquiera puede descargarla, copiar la clave y, si sigue activa, entrar al servicio al que pertenece.', 'Cambia o anula la clave de inmediato en el servicio que la emitió. Después reconstruye la imagen sin la clave y borra las versiones viejas que la contienen.')
ON CONFLICT (code) DO NOTHING;

-- code no es único por sí solo en scoring_rules (UNIQUE (rule_set_id, code)),
-- por eso la FK va de las reglas a los textos y no al revés.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'scoring_rules_code_texts_fk'
                    AND conrelid = 'public.scoring_rules'::regclass) THEN
    ALTER TABLE scoring_rules
      ADD CONSTRAINT scoring_rules_code_texts_fk FOREIGN KEY (code) REFERENCES scoring_rule_texts (code);
  END IF;
END $$;

GRANT SELECT ON scoring_rule_texts TO cirdan_app;

COMMIT;
